from itertools import combinations
from math import isfinite


def validate_rectangles(rectangles, *, allow_rotation=False):
    """Validate mappings with id, x, y, width and height; return error strings."""
    errors = []
    valid = []
    orientations = {(12, 8)}
    if allow_rotation:
        orientations.add((8, 12))

    for index, rect in enumerate(rectangles):
        label = rect.get("id", f"rectangle {index + 1}")
        try:
            x, y, w, h = (rect[k] for k in ("x", "y", "width", "height"))
        except KeyError as exc:
            errors.append(f"{label}: missing {exc.args[0]}")
            continue

        if not all(isinstance(v, (int, float)) and not isinstance(v, bool)
                   and isfinite(v) for v in (x, y, w, h)):
            errors.append(f"{label}: coordinates and dimensions must be finite numbers")
            continue
        if w <= 0 or h <= 0:
            errors.append(f"{label}: dimensions must be positive")
            continue
        if (w, h) not in orientations:
            errors.append(f"{label}: orientation or dimensions {w} × {h} not permitted")
        if not (1 <= x and x + w <= 41 and 1 <= y and y + h <= 29):
            errors.append(f"{label}: outside usable area")
        valid.append((label, x, y, w, h))

    for a, b in combinations(valid, 2):
        la, xa, ya, wa, ha = a
        lb, xb, yb, wb, hb = b
        if xa < xb + wb and xb < xa + wa and ya < yb + hb and yb < ya + ha:
            errors.append(f"{la} and {lb}: positive-area overlap")
    return errors
